import { Mesh, PlaneGeometry, Object3D, Color, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} textContent
 * @property {Object} colors
 * @property {{position: [number, number, number], rotation: [number, number, number], scale: [number, number, number]}} scenePlacement
 * @property {string} imageUrl
 * @property {Array<{name:string, params:any}>} cinematicPrimitives
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>import('three/webgpu').Texture} textureLoader
 * @property {(url:string)=>Promise<any>} glbLoader
 * @property {Object<string,Function>} primitives
 * @property {Function} fontAtlas
 * @property {Function} [emit] - optional emit helper
 */

/**
 * Create a journal card node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  // Root container
  const root = new Object3D();

  // Apply scene placement
  const [px, py, pz] = config.scenePlacement?.position ?? [0, 0, 0];
  const [rx, ry, rz] = config.scenePlacement?.rotation ?? [0, 0, 0];
  const [sx, sy, sz] = config.scenePlacement?.scale ?? [1, 1, 1];
  root.position.set(px, py, pz);
  root.rotation.set(rx, ry, rz);
  root.scale.set(sx, sy, sz);

  // Load texture for the plane background
  const texture = ctx.textureLoader(config.imageUrl);

  // Plane geometry (unit size – can be resized with scale if needed)
  const geometry = new PlaneGeometry(1, 1);

  // Basic material with the loaded texture
  const material = new MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    color: new Color(0xffffff)
  });

  const plane = new Mesh(geometry, material);
  plane.castShadow = false;
  plane.receiveShadow = false;
  root.add(plane);

  // -----------------------------------------------------------------
  // Text rendering via fontAtlas (MSDF)
  // -----------------------------------------------------------------
  // Expected fontAtlas signature: (text:string, options?:Object) => THREE.Object3D
  // We pass the requested atlas region and styling hints.
  const textMesh = ctx.fontAtlas(config.textContent, {
    atlasIndex: 0,
    sourceRect: [0, 0, 512, 320],
    // style hints – the concrete implementation can interpret them.
    style: {
      fontFamily: 'Lora',
      weight: 400,
      size: 0.34, // approximate scene‑unit height for headline
      color: config.colors.ink
    }
  });

  // Slightly offset the text forward so it isn’t z‑fighting the plane
  if (textMesh && textMesh.position) textMesh.position.z = 0.01;
  root.add(textMesh);

  // -----------------------------------------------------------------
  // Interaction handling (GSAP animations)
  // -----------------------------------------------------------------
  const originalY = plane.position.y;
  const hoverAnim = { tween: null };
  const clickAnim = { tween: null };

  const handlers = {
    hover: () => {
      // rise‑in (subtle 0.15 scene units)
      if (hoverAnim.tween) hoverAnim.tween.kill();
      hoverAnim.tween = gsap.to(plane.position, {
        y: originalY + 0.15,
        duration: 0.7,
        ease: "power3.out"
      });
    },
    leave: () => {
      if (hoverAnim.tween) hoverAnim.tween.kill();
      hoverAnim.tween = gsap.to(plane.position, {
        y: originalY,
        duration: 0.3,
        ease: "power3.in"
      });
    },
    click: () => {
      // press‑down animation
      if (clickAnim.tween) clickAnim.tween.kill();
      clickAnim.tween = gsap.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: "back.out(1.7)",
        onComplete: () => {
          gsap.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.1 });
        }
      });
      // Emit navigation event if an emitter is provided
      if (typeof ctx.emit === "function") {
        ctx.emit('hub-journal.select');
      }
    }
  };

  // Attach handlers to userData for external systems to bind
  root.userData.handlers = handlers;

  // -----------------------------------------------------------------
  // Apply cinematic primitives if any are listed (none for this node)
  // -----------------------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives?.[prim.name];
      if (typeof fn === "function") {
        fn(root, prim.params);
      }
    }
  }

  // -----------------------------------------------------------------
  // Cleanup routine
  // -----------------------------------------------------------------
  root.userData.cleanup = () => {
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // Release texture if it was created exclusively for this node
    if (texture && texture.dispose) texture.dispose();

    // Kill any GSAP tweens
    gsap.killTweensOf(plane.position);
    gsap.killTweensOf(root.scale);
    // Remove references
    root.traverse(child => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose && child.material.dispose();
    });
  };

  return root;
}
